import sys
from collections import deque

class T:
    __slots__ = ('v', 'l', 'r')
    def __init__(self, v=0, l=None, r=None):
        self.v = v; self.l = l; self.r = r

def build(arr):
    if not arr or arr[0]=='n':
        return None
    r = T(int(arr[0]))
    q = deque([r]); i = 1
    while q and i < len(arr):
        n = q.popleft()
        if i < len(arr) and arr[i] != 'n':
            n.l = T(int(arr[i])); q.append(n.l)
        i += 1
        if i < len(arr) and arr[i] != 'n':
            n.r = T(int(arr[i])); q.append(n.r)
        i += 1
    return r

def average_brute(root):
    res = []
    q = deque([root])
    while q:
        s, cnt = 0, 0
        for _ in range(len(q)):
            n = q.popleft()
            s += n.v
            cnt += 1
            if n.l: q.append(n.l)
            if n.r: q.append(n.r)
        res.append(s / cnt)
    return res

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    root = build(data[1:1+n])
    print(' '.join(f'{x:.1f}' for x in average_brute(root)))

import sys
from collections import deque

class T:
    __slots__ = ('v', 'l', 'r')
    def __init__(self, v=0, l=None, r=None):
        self.v = v; self.l = l; self.r = r

def build(arr):
    if not arr or arr[0]=='n':
        return None
    r = T(int(arr[0]))
    q = deque([r]); i = 1
    while q and i < len(arr):
        n = q.popleft()
        if i < len(arr) and arr[i] != 'n':
            n.l = T(int(arr[i])); q.append(n.l)
        i += 1
        if i < len(arr) and arr[i] != 'n':
            n.r = T(int(arr[i])); q.append(n.r)
        i += 1
    return r

def average_opt(root):
    res = []
    q = deque([(root, 0)])
    sums = []
    cnts = []
    while q:
        n, d = q.popleft()
        if d == len(sums):
            sums.append(n.v); cnts.append(1)
        else:
            sums[d] += n.v; cnts[d] += 1
        if n.l: q.append((n.l, d + 1))
        if n.r: q.append((n.r, d + 1))
    res = [s / c for s, c in zip(sums, cnts)]
    return res

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    root = build(data[1:1+n])
    print(' '.join(f'{x:.1f}' for x in average_opt(root)))
